<?php
namespace Database\Seeders;
use App\Models\City; use App\Models\Province; use Illuminate\Database\Seeder; use Illuminate\Support\Str;
class CitySeeder extends Seeder { public function run():void {$map=['تهران'=>['تهران','ری','شمیرانات','شهریار'],'اصفهان'=>['اصفهان','کاشان','خمینی‌شهر','نجف‌آباد'],'فارس'=>['شیراز','مرودشت','جهرم','فسا'],'خراسان رضوی'=>['مشهد','نیشابور','سبزوار','تربت حیدریه'],'خوزستان'=>['اهواز','دزفول','آبادان','خرمشهر'],'مازندران'=>['ساری','آمل','بابل','نوشهر'],'گیلان'=>['رشت','انزلی','لاهیجان','رودسر'],'آذربایجان شرقی'=>['تبریز','مراغه','مرند','اهر'],'آذربایجان غربی'=>['ارومیه','خوی','میاندوآب','مهاباد'],'کرمان'=>['کرمان','رفسنجان','سیرجان','جیرفت'],'کرمانشاه'=>['کرمانشاه','اسلام‌آباد غرب','کنگاور','سنقر'],'همدان'=>['همدان','ملایر','نهاوند','تویسرکان'],'یزد'=>['یزد','میبد','اردکان','بافق'],'سمنان'=>['سمنان','شاهرود','دامغان','گرمسار'],'البرز'=>['کرج','نظرآباد','هشتگرد','طالقان'],'قم'=>['قم'],'قزوین'=>['قزوین','تاکستان','آبیک'],'گلستان'=>['گرگان','گنبد کاووس','علی‌آباد کتول'],'مرکزی'=>['اراک','ساوه','خمین'],'هرمزگان'=>['بندرعباس','میناب','قشم','بندر لنگه']]; foreach($map as $provinceName=>$cities){$p=Province::where('name',$provinceName)->first();foreach($cities as $name)City::updateOrCreate(['province_id'=>$p->id,'name'=>$name],['slug'=>Str::slug($name)]);}} }
